    btn: (t, on, attrs = '', cls = '') => `<button class="itab ${cls}" role="tab" aria-selected="${!!on}" title="${esc(t.label)}" aria-label="${esc(t.label)}" ${attrs}>${M.icon(t.icon, 20)}<span class="itl">${esc(t.label)}</span></button>`,
