        if (!lock && l.attributes.code_format) M.moreInfo(card, E.lock);
        else M.call(h, 'lock', lock ? 'lock' : 'unlock', { entity_id: E.lock }).then(() => t(lock ? 'Dørlås låst' : 'Dørlås låst opp')).catch(() => {});
