  M.hjemRuterInfo = ruterInfo;
  const RUTER_IC = { bus: 'mdi:bus', coach: 'mdi:bus', tram: 'mdi:tram', metro: 'mdi:subway-variant', rail: 'mdi:train', water: 'mdi:ferry', air: 'mdi:airplane' };
