      s.addEventListener('click', (e) => { const b = e.composedPath().find((n) => n.dataset && n.dataset.d); if (!b) return; M.haptic('selection'); ed.u.pwTmr = b.dataset.d === 'tomorrow'; paintPreview(ed, over); });
