  const DC_TYPE = { door: 'door', garage_door: 'door', opening: 'door', window: 'window', motion: 'motion', occupancy: 'presence', presence: 'presence' };
  const AUTO_DC = ['door', 'window', 'garage_door', 'opening', 'motion', 'occupancy'];
