    for (let i = 1; i < r; i++) s += `<path d="M${x} ${y + (h * i) / r}H${x + w}" stroke="${fr}" stroke-width="1"/>`;
    if (o.sill !== false) s += `<rect x="${x - 2.6}" y="${y + h + 1}" width="${w + 5.2}" height="1.9" rx=".5" fill="${fr}"/>`;
