  const vLines = (x0, x1, y0, y1, step, op = 0.12) => { let d = ''; for (let x = x0 + step; x < x1; x += step) d += `M${x} ${y0}V${y1}`; return `<path d="${d}" stroke="#000" stroke-opacity="${op}" stroke-width=".7"/>`; };
