  const GREEN = 'var(--green, #66d19e)';
  const COLS = ['var(--red)', 'var(--orange)', 'var(--yellow)', 'var(--lime)', 'var(--green)', 'var(--blue)', 'var(--light-blue)', 'var(--purple)', 'var(--pink)'];
