          const [grp, id] = [v.split('.')[0], v.slice(v.indexOf('.') + 1)];
          if (grp === 'rooms') return emit({ editor: 'room', area: id });
          if (/^room-/.test(id)) return emit({ editor: 'room', area: id.slice(5) });
