  const pDate = (v) => { if (v == null || v === '') return null; if (v instanceof Date) return v; const s = String(v); if (/^\d{4}-\d\d-\d\d$/.test(s)) return fromKey(s); const d = new Date(s); return isNaN(d) ? null : d; };
