    const vac = vacOf(h, c);
    if (vac === DEF_ENT.vacuum && has(h, DEF_ENT[k])) return DEF_ENT[k]; // brukerens oppsett gjelder bare for brukerens støvsuger
    const f = ENTK[k] && ENTK[k][4], o = objOf(vac);
