  function setRows(ed, fn) { const W = rowsWork(ed._config || {}); fn(W); ed._set('rows', rowsOut(W)); }
  const curTab = (ed, c) => { const T = tabDefs(c), v = RT.get(cid(ed)); return T.some((t) => t.key === v) ? v : (T[0] || {}).key; };
